# log-page 的 CURSOR：* 或 <sha256>:<offset>，sha256 为 64 位小写十六进制，
# offset 为 0 或无前导零正整数（任意长度）
_PAGE_CURSOR_RE = re.compile(r"\*|[0-9a-f]{64}:(?:0|[1-9][0-9]*)")


def _page_prefix_bytes(doc):
    """log-page 末项摘要文本：前四键紧凑 UTF-8 加 LF。"""
