        with open(log_path, "rb") as handle:
            # 分块至多 65536 字节读取，输入上限按原始字节计，等于上限合法
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    if log_raw is None:
        _fail("log_limit")

    return result


def simulate(events, age, observer=None):
    fdb = {}  # (vlan, mac) -> [port, seen]
    if observer is not None:  # record/replay：逐事件记录 applied
        observer["items"] = []
    for t, port, mac, vlan in events:
        # 事件前该 (vlan, mac) 的 [port, seen]（不存在为 None）
        previous = tuple(fdb[(vlan, mac)]) if (vlan, mac) in fdb else None
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        fdb[(vlan, mac)] = [port, t]
        if observer is not None:
            # 含 port、seen 的表项与事件前不同（新学习、迁移或 seen 推进）
            # 才 applied；同时刻同口重复学习幂等，applied=False
            applied = previous != (port, t)
            observer["items"].append(
                {"kind": "learn", "t": t, "applied": applied, "output": None}
            )
    entries = []
    for (vlan, mac), (port, seen) in sorted(fdb.items(), key=lambda item: item[0]):
        entries.append(
            {"vlan": vlan, "mac": mac, "port": port, "seen": seen}
        )
    return {"fdb": entries}


def fdb_work(events, age, limit):
    """按既有老化/学习规则用独立空映射无副作用预演并累计工作量。

    逐事件以老化前表项数 K 计 K+1（首事件成本 1，重复源与迁移同样计费）；
    累计等于上限合法，首次超过上限即抛 FdbWorkLimit。
    """
    fdb = {}  # (vlan, mac) -> [port, seen]
    work = 0
    for t, port, mac, vlan in events:
        work += len(fdb) + 1
        if work > limit:
            raise FdbWorkLimit
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        fdb[(vlan, mac)] = [port, t]


def validate_forward_config(config):
    if not isinstance(config, dict) or frozenset(config) != CONFIG_KEYS:
